cd /tmp/shurik-workspace-ewkjjA && git show origin/main:S04/E11.md | head -14 && cd /tmp/joey-convo && python3 - <<'EOF'
import subprocess, re
def sh(*a):
    return subprocess.run(['git','-C','/tmp/joey-convo']+list(a),capture_output=True,text=True).stdout
all_sha={}
for b in ['rachel','monica','phoebe','chandler','ross','joey']:
    for sha in sh('log','--format=%H','origin/friend/'+b).split():
        msg=sh('show','-s','--format=%B',sha)
        if 'Friend-Message: 1' in msg and re.search(r'^Episode: S04/E11\s*$',msg,re.M):
            all_sha[sha]=b
main=sh('show','origin/main:S04/E11.md')
present=set(re.findall(r'@ ([0-9a-f]{40})',main))
missing=sorted(s for s in all_sha if s not in present)
print("E11 total",len(all_sha),"present",len(present&set(all_sha)),"missing",len(missing))
print(' '.join(missing))
EOF
